import urllib.request
import urllib.error
import time

class APIClientError(Exception):
    """Base exception for APIClient"""
    pass

class RateLimitError(APIClientError):
    """Raised when 429 persists after retries"""
    pass

class ServerError(APIClientError):
    """Raised when 5xx persists after retries"""
    pass

class ClientError(APIClientError):
    """Raised when 4xx (non-429) occurs"""
    pass

class ConnectionError(APIClientError):
    """Raised when network errors persist after retries"""
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url.rstrip('/')
        self.timeout = timeout

    def get(self, path):
        url = f"{self.base_url}/{path.lstrip('/')}"

        # Retry configurations: (max_retries, backoff_strategy_type)
        # 429: 3 retries, exponential [0.5, 1, 2]
        # 5xx: 1 retry, constant [1]
        # URLError: 1 retry, constant [1]

        rate_limit_retries = 0
        server_error_retries = 0
        network_error_retries = 0

        while True:
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')

            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if rate_limit_retries < 3:
                        sleep_time = 0.5 * (2 ** rate_limit_retries)
                        time.sleep(sleep_time)
                        rate_limit_retries += 1
                        continue
                    else:
                        raise RateLimitError(f"Rate limit exceeded after retries: {e.code}")

                elif 500 <= e.code < 600:
                    if server_error_retries < 1:
                        time.sleep(1)
                        server_error_retries += 1
                        continue
                    else:
                        raise ServerError(f"Server error: {e.code}")

                elif 400 <= e.code < 500:
                    raise ClientError(f"Client error: {e.code}")

                else:
                    raise APIClientError(f"Unexpected HTTP error: {e.code}")

            except urllib.error.URLError as e:
                if network_error_retries < 1:
                    time.sleep(1)
                    network_error_retries += 1
                    continue
                else:
                    raise ConnectionError(f"Network error: {e.reason}")
